// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems, Neuron} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;
    address user = address(0xBEEF);

    function setUp() public { c = new GameItems(address(this), address(this)); }

    function testFuzz_property(uint16 dailyAllowance, uint256 quantity) public {
        vm.assume(dailyAllowance > 0);
        quantity = bound(quantity, 1, dailyAllowance);

        Neuron n = new Neuron(address(this), address(this), address(this));
        c.instantiateNeuronContract(address(n));
        n.addSpender(address(c));

        // create a non-finite-supply, zero-price item with the fuzzed daily allowance
        c.createGameItem("item", "ipfs://x", false, true, 0, 0, dailyAllowance);

        vm.prank(user);
        c.mint(0, quantity);

        // Replenish time was set to now + 1 day, so the getter reports the stored value,
        // which the reference decremented by the purchased quantity.
        assertEq(
            c.getAllowanceRemaining(user, 0),
            dailyAllowance - quantity,
            "allowance must decrease by purchased quantity"
        );
    }
}
